const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base=await fetch('scenario.json').then(r=>{if(!r.ok)throw Error('scenario');return r.json()});
let scenario=structuredClone(base),state={reports:[],tasks:{},events:[]},selected='b',mode='compare',connected=true,urls={};
try{const s=JSON.parse(localStorage.getItem('rescuemap-v2'));if(s?.scenario?.buildings?.length===3){scenario=s.scenario;state=s.state}}catch{}
const save=()=>{try{localStorage.setItem('rescuemap-v2',JSON.stringify({scenario,state}))}catch{toast('לא ניתן לשמור בדפדפן זה. השינויים נשמרים בזיכרון בלבד.')}};
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
function log(t){state.events.unshift({time:new Date().toLocaleTimeString('he-IL',{timeZone:'Asia/Jerusalem'}),text:t});save()}
function render(){
$('#title').textContent=scenario.title;$('#subtitle').textContent=scenario.subtitle;$('#beforeDate').textContent=scenario.beforeDate;$('#afterDate').textContent=scenario.afterDate;
$('#stats').innerHTML=[['03','מבנים במעקב','גזרת תרגיל'],[scenario.buildings.reduce((n,b)=>n+(b.people??0),0),'אנשים לפי דיווח','טרם אימות בשטח'],[Object.keys(state.tasks).length,'משימות שהוקצו','בתוך הדפדפן בלבד'],['02','מקורות צילום','בסיס + רחפן · מדומה']].map(([n,t,s])=>`<div class="stat"><strong>${esc(n)}</strong><div>${esc(t)}<small>${esc(s)}</small></div></div>`).join('');
$('#buildings').innerHTML=[...scenario.buildings].sort((a,b)=>(b.people??-1)-(a.people??-1)).map(b=>`<button class="building ${b.id===selected?'selected':''}" data-building="${b.id}"><div class="building-head"><h3>${esc(b.name)}</h3><b class="number">${b.people??'?'}</b></div><p>${esc(b.address)} · ${b.people===null?'נוכחות לא ידועה':'אנשים מדווחים'}</p><span class="pill ${b.id==='b'?'amber':''}">${esc(b.damage)}</span></button>`).join('');
$('#pins').innerHTML=$('#markers').checked?scenario.buildings.map(b=>`<button class="pin ${b.id===selected?'selected':''}" style="left:${b.x}%;top:${b.y}%" data-building="${b.id}">${esc(b.name)} · ${b.people??'?'}</button>`).join(''):'';
$$('[data-building]').forEach(el=>el.onclick=()=>{selected=el.dataset.building;render()});
const b=scenario.buildings.find(b=>b.id===selected)||scenario.buildings[0];
$('#detail').innerHTML=`<div class="panel-title"><h2>${esc(b.name)} · ${esc(b.address)}</h2><span class="pill amber">${esc(b.confidence)}</span></div><div class="detail-grid">${[['קומות לפני האירוע',b.floors+' · נתון תרחיש'],['יחידות דיור',b.apartments+' · נתון תרחיש'],['אנשים לפי דיווח',b.people??'לא ידוע'],['נזק חיצוני משוער',b.damage],['מקור דיווח',b.source+' · '+b.reportTime],['גישה',b.access],['חיישן משויך',b.sensor],['משימה',state.tasks[b.id]||'טרם הוקצתה']].map(([k,v])=>`<div class="field"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div><p class="muted">צילום אינו מלמד על מספר לכודים או יציבות מבנה. הסדר המוצג הוא עזר להשוואה; נדרשת החלטת מפקד.</p><div class="detail-actions"><select id="team" aria-label="צוות לתרגיל"><option>צוות חילוץ 1</option><option>צוות חילוץ 2</option></select><button id="assign" class="primary" ${state.tasks[b.id]?'disabled':''}>${state.tasks[b.id]?'משימה הוקצתה':'אשר הקצאה בתרגיל'}</button></div>`;
$('#assign').onclick=()=>{if(!connected)return toast('אין חיבור בהדמיה. לא ניתן לאשר הקצאה.');state.tasks[b.id]=$('#team').value;log(`${state.tasks[b.id]} הוקצה ל${b.name} בהדמיה`);render();toast('המשימה נשמרה בדפדפן לתרגיל בלבד')};
$('#timeline').innerHTML=[...state.events,{time:'09:12',text:'נקלט תצלום רחפן D01 · הדמיה'},{time:'09:11',text:'אות תנועה בחיישן S02 · לבדיקה'},{time:'09:10',text:'דיווח על 19 אנשים בבניין ב׳ · טרם אומת'},{time:'09:08',text:'דיווח על 5 אנשים בבניין א׳ · טרם אומת'}].slice(0,8).map(e=>`<div class="event-row"><time>${esc(e.time)}</time><p>${esc(e.text)}</p></div>`).join('');
$('#reportCount').textContent=state.reports.length;
$('#reportList').innerHTML=state.reports.length?state.reports.map(r=>`<div class="report-item"><b>${esc(r.building)} · ${r.people} אנשים</b><p>${esc(r.condition)} · ${esc(r.time)}</p><p>${esc(r.notes)}</p><span class="pill ${r.pending?'amber':''}">${r.pending?'ממתין לחיבור — לא התקבל בחמ״ל':'התקבל בהדמיה — ממתין לבדיקת חפיפה'}</span></div>`).join(''):'<p class="muted">עדיין לא נוספו דיווחים בתרגיל הזה.</p>';
$('#network').textContent=connected?'● מחובר בהדמיה':'○ מנותק בהדמיה';$('#networkText').textContent=connected?'סלולר פעיל בהדמיה · Starlink כנתיב חלופי מתוכנן':'ניתוק מדומה · מידע אחרון שמור בדפדפן';applyMode();}
function applyMode(){const n=mode==='before'?100:mode==='after'?0:Number($('#split').value);$('#beforeImage').style.clipPath=`inset(0 ${100-n}% 0 0)`;$('#divider').style.left=n+'%';$('#divider').hidden=mode!=='compare';$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));}
$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;applyMode()});$('#split').oninput=()=>{mode='compare';applyMode()};$('#markers').onchange=render;
$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('.view').forEach(v=>v.classList.toggle('hidden',v.id!==b.dataset.tab));$$('[data-tab]').forEach(t=>t.classList.toggle('active',t===b));if(b.dataset.tab==='edit')fillEditor()});
$('#network').onclick=()=>{connected=!connected;if(connected){let count=0;for(const r of state.reports)if(r.pending){r.pending=false;count++}if(count)toast(`${count} דיווחים התקבלו בהדמיה וממתינים לבדיקת חפיפה`);save()}render()};
$('#reportBuilding').innerHTML=scenario.buildings.map(b=>`<option value="${b.id}">${esc(b.name)} · ${esc(b.address)}</option>`).join('');
$('#reportForm').onsubmit=e=>{e.preventDefault();const people=Number($('#people').value);if(!Number.isInteger(people)||people<1||people>1000)return;const b=scenario.buildings.find(b=>b.id===$('#reportBuilding').value);state.reports.unshift({id:(crypto.randomUUID?.() || `demo-${Date.now()}-${Math.random().toString(16).slice(2)}`),building:b.name,people,condition:$('#condition').value,notes:$('#notes').value,pending:!connected,time:new Date().toLocaleTimeString('he-IL',{timeZone:'Asia/Jerusalem'})});log('נוסף דיווח חדש · ממתין לבדיקת חפיפה');render();toast(connected?'הדיווח התקבל בהדמיה. צוות לא הוזנק.':'נשמר בדפדפן וממתין לחיבור בהדמיה.');$('#notes').value=''};
function fillEditor(){$('#editTitle').value=scenario.title;$('#editRows').innerHTML=scenario.buildings.map(b=>`<div class="edit-card"><h3>${esc(b.name)}</h3><label>מספר אנשים מדווח<input data-count="${b.id}" type="number" min="0" max="1000" value="${b.people??''}" placeholder="ריק = לא ידוע"></label><label>מצב המבנה<input data-damage="${b.id}" value="${esc(b.damage)}" maxlength="100"></label><label>מקור הדיווח<input data-source="${b.id}" value="${esc(b.source)}" maxlength="100"></label></div>`).join('')}
$('#editForm').onsubmit=e=>{e.preventDefault();scenario.title=$('#editTitle').value;for(const b of scenario.buildings){const v=$(`[data-count="${b.id}"]`).value;b.people=v===''?null:Number(v);b.damage=$(`[data-damage="${b.id}"]`).value;b.source=$(`[data-source="${b.id}"]`).value}save();render();toast('התרחיש עודכן בדפדפן')};
$('#export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(scenario,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='scenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
$('#reset').onclick=()=>{scenario=structuredClone(base);state={reports:[],tasks:{},events:[]};save();render();fillEditor();toast('נתוני ההדגמה אופסו')};
for(const type of ['before','after'])$('#'+type+'File').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>15*1024*1024){toast('בחרו PNG, JPEG או WebP עד 15MB');return}if(urls[type])URL.revokeObjectURL(urls[type]);urls[type]=URL.createObjectURL(f);const el=$('#'+type+'Image');el.style.backgroundImage=`url("${urls[type]}")`;el.style.backgroundSize='100% 100%';toast('התמונה הוחלפה מקומית בלבד; יש להחליף גם את התמונה המקבילה לפי הצורך')};
render();
